"""Creates a local, accessible information preview; it does NOT render the WebGL scene."""
import json, pathlib
root=pathlib.Path(__file__).resolve().parents[1]
data=json.loads((root/'public/world-data.json').read_text())
script=json.dumps({k:data[k] for k in ['timeline','qualifications','skillGroups']},ensure_ascii=False).replace('</','<\\/')
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>GeoVerse V4 · Terrain Edition Preview</title><style>
:root{font-family:system-ui,Arial,sans-serif;background:#103b44;color:#f6ead1}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 45% 10%,#225968,#0a2a36 65%);min-height:100vh}main{max-width:1500px;margin:auto;padding:24px}header{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:0 0 18px}.logo{font-size:20px;font-weight:900;letter-spacing:.11em}.logo span{color:#8ad6c7}header small{letter-spacing:.1em;color:#bdd1cd;font-weight:700;text-align:right}.visual{width:100%;display:block;border:1px solid #588d8e;border-radius:18px;box-shadow:0 26px 66px #0005}.note{color:#bdd5cd;font-size:12px;margin:10px 0 26px}.navigator{border:1px solid #598b8a;background:#183f4de8;border-radius:18px;padding:20px;box-shadow:0 16px 44px #001d28}.tabs{display:flex;gap:9px;flex-wrap:wrap}.tabs button{border:1px solid #86b6ac85;background:#235765;color:#ecf4e4;border-radius:11px;padding:11px 17px;font-weight:800;cursor:pointer}.tabs button.active{background:linear-gradient(115deg,#6fa9a4,#a08bd5);color:#102e3a}.list{display:grid;grid-template-columns:repeat(auto-fit,minmax(215px,1fr));gap:10px;margin-top:18px}.tile{border:1px solid #59877e77;background:#174450;color:#eff4e7;border-radius:13px;text-align:left;padding:15px;cursor:pointer;line-height:1.5}.tile:hover,.tile:focus-visible{background:#245d69}.tile strong{display:block;font-size:14px}.tile small{display:block;font-size:11px;margin:6px 0;color:#d3be8e}.tile span{font-size:11px;color:#b7cfc9}.details{border:1px solid #69a29e;background:#22505c;border-radius:16px;padding:21px;margin-top:14px;min-height:80px}.details h2{margin:0 0 10px;font-size:23px;color:#f8dfaf}.details p,.details li{line-height:1.7;color:#d3e3dd}.details .role{color:#b8d7ee;font-weight:700}.details ul{padding-left:19px}.button{display:inline-block;border-radius:11px;background:#b52547;color:white;text-decoration:none;padding:11px 15px;font-weight:850}footer{color:#a8c3c0;font-size:11px;margin:22px 0}@media(max-width:700px){main{padding:12px}header{align-items:flex-start;flex-direction:column}.logo{font-size:15px}.navigator{padding:13px}.tabs button{padding:10px 12px}.details{padding:15px}}</style></head><body><main><header><div class="logo">✳ <span>GEO</span>VERSE / FAIZAN TAYYAB</div><small>TOPOGRAPHY EDITION · 3D WORLD SOURCE INCLUDED</small></header><img class="visual" src="./terrain-topography-preview.png" alt="Illustrative raised topographic terrain with contour lines, and professional career station markers."/><p class="note">This image visualizes the exact heightfield used in the new Three.js source. It is an illustrative elevation render—not a screenshot of the browser WebGL application. The full application adds buildings, the walking character, animated connections and a red London telephone kiosk.</p><section class="navigator"><div class="tabs"><button data-tab="timeline" class="active">Experience &amp; education</button><button data-tab="qualifications">Certifications</button><button data-tab="skillGroups">Skillset</button></div><div class="list" id="list"></div><article class="details" id="details"><h2>Choose a chapter</h2><p>Select a card to view the CV-based experience. In the full Three.js world, the same chapter becomes a 3D destination.</p></article></section><footer>Source: CV_2025.docx · Published contact: <a href="https://www.linkedin.com/in/ftayyab" target="_blank" rel="noopener noreferrer" style="color:#a8d6f8">LinkedIn via the 3D London phone box</a></footer></main><script>const DATA=__DATA__;let tab='timeline';const list=document.getElementById('list'),details=document.getElementById('details');const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function display(i){const item=DATA[tab][i];if(!item)return;if(tab==='timeline'){details.innerHTML='<h2>'+esc(item.company)+'</h2><div class="role">'+esc(item.role)+' · '+esc(item.date)+'</div><p>'+esc(item.story)+'</p><ul>'+item.achievements.map(v=>'<li>'+esc(v)+'</li>').join('')+'</ul><p>'+item.technologies.map(v=>'<span style="display:inline-block;margin:4px;padding:6px 10px;border-radius:9px;background:#366b74">'+esc(v)+'</span>').join('')+'</p>'}else if(tab==='qualifications'){details.innerHTML='<h2>'+esc(item.name)+'</h2><p>'+esc(item.issuer)+' · '+esc(item.year)+'</p><p>Professional qualification or course listed in the CV.</p>'}else{details.innerHTML='<h2>'+esc(item.name)+'</h2><p>'+item.skills.map(v=>'<span style="display:inline-block;margin:4px;padding:6px 10px;border-radius:9px;background:#366b74">'+esc(v)+'</span>').join('')+'</p>'}}function render(){document.querySelectorAll('.tabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));list.innerHTML='';DATA[tab].forEach((item,i)=>{const b=document.createElement('button');b.className='tile';b.innerHTML='<strong>'+esc(item.company||item.name)+'</strong><small>'+esc(item.date||item.year||'TECHNICAL SKILLS')+'</small><span>'+esc(item.role||item.group||((item.skills||[]).length+' capabilities'))+'</span>';b.onclick=()=>display(i);list.append(b)});display(0)}document.querySelectorAll('.tabs button').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});render();</script></body></html>'''
(root/'illustrative-preview.html').write_text(html.replace('__DATA__',script),encoding='utf-8')
print('Wrote new illustrated preview')
